/*
 * Placeholder service worker.
 *
 * Regenerated from your own Firebase App Config by
 * UltimatePushNotifications\admin\options\functions\AppConfig::save(). It ships
 * empty on purpose — a real configuration must never be committed to the
 * repository or distributed in the plugin package.
 *
 * Registering an empty service worker is harmless: it simply receives no
 * messages until a configuration has been saved.
 */
self.addEventListener("install", function () {
	self.skipWaiting();
});
